function readCreation(body) {
  const id = body?.contactId;
  const contactId = typeof id === "number" && Number.isSafeInteger(id) ? String(id) : id;
  if (
    body?.event !== "contact.creation" ||
    typeof contactId !== "string" ||
    !/^[1-9]\d*$/.test(contactId)
  ) {
    throw new Error("Expected a HubSpot contact.creation event with a Record ID");
  }
  return { contactId };
}
return [{ json: readCreation($input.first().json.body) }];

function buildLookup({ contactId, record }) {
  if (record?.id !== contactId || record.archived)
    throw new Error("HubSpot returned a different or archived contact");
  const email = record.properties?.email;
  const hasEmail = typeof email === "string" && /^[^\s@]+@[^\s@]+$/.test(email.trim());
  const endpoint = "https://api.exactbuyer.com/v1/enrich";
  const url = hasEmail
    ? endpoint +
      "?email=" +
      encodeURIComponent(email.trim()) +
      "&required=work_email%2Cpersonal_email%2Cemail"
    : endpoint;
  return { hasEmail, url, email: hasEmail ? email.trim() : "" };
}
const { contactId } = $("Check contact creation event").first().json;
const result = buildLookup({ contactId, record: $input.first().json });
return result.hasEmail ? [{ json: { url: result.url, email: result.email } }] : [];

function mapResult({ status, body, queryEmail }) {
  if (status === 404) return { matched: false, properties: {} };
  if (
    status !== 200 ||
    !body?.result ||
    typeof body.result !== "object" ||
    Array.isArray(body.result)
  ) {
    throw new Error("ExactBuyer lookup failed (HTTP " + status + ")");
  }
  const { result } = body;
  const normalizeEmail = (entry) => (typeof entry === "string" ? entry.trim().toLowerCase() : "");
  const optionalList = (entry) => (Array.isArray(entry) ? entry : []);
  const addresses = [
    result.current_work_email,
    ...optionalList(result.other_current_work_emails).map((entry) => entry?.work_email),
    ...optionalList(result.personal_emails),
  ];
  const expected = normalizeEmail(queryEmail);
  if (!expected || !addresses.some((address) => normalizeEmail(address) === expected)) {
    return { matched: false, properties: {} };
  }
  const source = {
    firstname: result.first_name,
    lastname: result.last_name,
    gender: result.gender,
    school: result.education?.[0]?.school?.name,
    country: result.location?.country,
    jobtitle: result.employment?.job?.title,
    company: result.employment?.name,
    company_size: result.employment?.size,
    phone: result.phone_numbers?.[0]?.E164,
  };
  const properties = Object.fromEntries(
    Object.entries(source)
      .filter(
        ([, entry]) =>
          (typeof entry === "string" && entry.trim()) ||
          (typeof entry === "number" && Number.isFinite(entry)),
      )
      .map(([key, entry]) => [key, String(entry).trim()]),
  );
  return { matched: Object.keys(properties).length > 0, properties };
}
const { contactId } = $("Check contact creation event").first().json;
const { statusCode, body } = $input.first().json;
const queryEmail = $("Prepare email lookup").first().json.email;
const result = mapResult({ status: statusCode, body, queryEmail });
return result.matched ? [{ json: { contactId, properties: result.properties } }] : [];

function confirmUpdate({ contactId, record }) {
  if (record?.id !== contactId || record.archived)
    throw new Error("HubSpot did not confirm the requested contact update");
  return { contactId };
}
const { contactId } = $("Check contact creation event").first().json;
return [{ json: confirmUpdate({ contactId, record: $input.first().json }) }];
